import { webkit } from 'playwright';
import fs from 'node:fs';
const base='https://hearframe-grand-hello-world-v4.onrender.com/ask/';
const result={checkedAt:new Date().toISOString(),base,steps:[],consoleErrors:[],pass:false};
async function waitText(page,selector,needle,timeout=20000){const t=Date.now();let last='';while(Date.now()-t<timeout){last=(await page.locator(selector).innerText()).trim();if(last.includes(needle))return last;if(/failed|error/i.test(last))throw Error(last);await page.waitForTimeout(120)}throw Error(`timeout ${needle}; last=${last}`)}
async function waitVideo(page,timeout=12000){const v=page.locator('.msg.bot:last-child video');await v.evaluate(el=>el.play());const t=Date.now();while(Date.now()-t<timeout){const s=await v.evaluate(el=>({t:el.currentTime,d:el.duration,ended:el.ended,paused:el.paused,rs:el.readyState,error:el.error?.code||null,src:el.currentSrc}));if(s.error)throw Error('media error '+s.error);if(s.ended||(Number.isFinite(s.d)&&s.d>0&&s.t>=Math.max(0,s.d-.04)))return s;await page.waitForTimeout(80)}const s=await v.evaluate(el=>({t:el.currentTime,d:el.duration,ended:el.ended,paused:el.paused,rs:el.readyState,error:el.error?.code||null,src:el.currentSrc}));throw Error('video clock timeout '+JSON.stringify(s))}
const b=await webkit.launch({headless:true});const c=await b.newContext({viewport:{width:1194,height:834},userAgent:'Mozilla/5.0 (iPad; CPU OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1'});const p=await c.newPage();p.on('console',m=>{if(m.type()==='error')result.consoleErrors.push(m.text())});p.on('pageerror',e=>result.consoleErrors.push('pageerror: '+e.message));try{const r=await p.goto(base+'?qa='+Date.now(),{waitUntil:'networkidle',timeout:30000});result.httpStatus=r?.status();result.title=await p.title();if(!result.title.includes('Ask Hearframe v0'))throw Error('wrong title '+result.title);await waitText(p,'#status','Corpus ready',20000);result.steps.push('page-corpus-ready');
async function ask(q,answer){await p.locator('#input').fill(q);await p.locator('#form').evaluate(f=>f.requestSubmit());await p.locator('.msg.bot:last-child .answer').waitFor({state:'visible',timeout:10000});const text=(await p.locator('.msg.bot:last-child .answer').innerText()).trim();if(text!==answer)throw Error(`answer mismatch for ${q}: ${text}`);const state=await waitVideo(p);result.steps.push(`answer:${answer}`);return state}
result.startVideo=await ask('Can I start?','You can begin.');result.changeVideo=await ask('How does change happen?','Change only happens when ordinary people get involved.');await p.locator('#input').fill('What is quantum entanglement?');await p.locator('#form').evaluate(f=>f.requestSubmit());await p.locator('.msg.bot:last-child .answer').waitFor({state:'visible',timeout:10000});const fallback=(await p.locator('.msg.bot:last-child .answer').innerText()).trim();if(!fallback.includes('do not have enough indexed speech'))throw Error('fallback missing: '+fallback);if(await p.locator('.msg.bot:last-child video').count())throw Error('fallback should not fabricate a video');result.steps.push('corpus-gap-safe');if(result.consoleErrors.length)throw Error('console errors '+JSON.stringify(result.consoleErrors));result.pass=true}catch(e){result.error=String(e?.stack||e)}finally{await b.close()}fs.writeFileSync('hearframe-grand-v4/ask/live-qa.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));if(!result.pass)process.exitCode=1;
